CREATE TABLE fee_plan_heads(owner_id text NOT NULL,account_id text NOT NULL,id uuid NOT NULL,revision bigint NOT NULL CHECK(revision>0),PRIMARY KEY(owner_id,id),UNIQUE(owner_id,account_id,id),FOREIGN KEY(owner_id,account_id) REFERENCES broker_accounts(owner_id,id));
CREATE TABLE fee_plan_revisions(owner_id text NOT NULL,id uuid NOT NULL,revision bigint NOT NULL,account_id text NOT NULL,provider_id text NOT NULL,effective_from date NOT NULL,effective_through date NOT NULL,components jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(owner_id,id,revision),FOREIGN KEY(owner_id,account_id,id) REFERENCES fee_plan_heads(owner_id,account_id,id),CHECK(effective_from<=effective_through));
CREATE TRIGGER fee_plan_immutable BEFORE UPDATE OR DELETE ON fee_plan_revisions FOR EACH ROW EXECUTE FUNCTION immutable_trade_ledger();
CREATE TABLE fee_plan_previews(token_hash text PRIMARY KEY,owner_id text NOT NULL,session_hash text NOT NULL,payload_hash text NOT NULL,account_revision bigint NOT NULL,expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '10 minutes',consumed_at timestamptz);
CREATE TABLE fee_plan_operations(owner_id text NOT NULL,request_id uuid NOT NULL,payload_hash text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(owner_id,request_id));
CREATE TRIGGER fee_plan_operation_immutable BEFORE UPDATE OR DELETE ON fee_plan_operations FOR EACH ROW EXECUTE FUNCTION immutable_trade_ledger();
